describe('Bulk Delete Selected Items from List', () => {
  beforeEach(() => {
    cy.visit('/list');
  });

  it('should successfully bulk delete multiple selected items', () => {
    // Verify list is visible and contains items
    cy.get('[data-testid="item-row"]').should('be.visible');
    cy.get('[data-testid="item-row"]').should('have.length.greaterThan', 0);

    // Select multiple items
    cy.get('[data-testid="item-row"]').first().click('[data-testid="select-checkbox"]').click();
    cy.get('[data-testid="item-row"]').eq(1).click('[data-testid="select-checkbox"]').click();
    cy.get('[data-testid="item-row"]').eq(3).click('[data-testid="select-checkbox"]').click();

    // Verify selection is active
    cy.get('[data-testid="select-checkbox"]').should('have.class', 'selected');

    // Click bulk delete button
    cy.get('[data-testid="bulk-delete-button"]').click();

    // Verify confirmation modal appears
    cy.get('[data-testid="confirm-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-modal"]').should('contain', 'Are you sure you want to delete');

    // Confirm deletion
    cy.get('[data-testid="confirm-delete-button"]').click();

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Items deleted successfully');

    // Verify items are removed from list
    cy.get('[data-testid="item-row"]').should('not.exist');
    cy.get('[data-testid="item-row"]').should('have.length', 0);
  });

  it('should handle edge case when no items are selected for bulk delete', () => {
    // Verify list is visible
    cy.get('[data-testid="item-row"]').should('be.visible');

    // Attempt to click bulk delete button without selecting any items
    cy.get('[data-testid="bulk-delete-button"]').click();

    // Verify error or warning message appears
    cy.get('[data-testid="warning-message"]').should('be.visible');
    cy.get('[data-testid="warning-message"]').should('contain', 'Please select at least one item to delete');

    // Verify no confirmation modal appears
    cy.get('[data-testid="confirm-modal"]').should('not.exist');

    // Verify list remains unchanged
    cy.get('[data-testid="item-row"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="item-row"]').first().should('contain', 'Item 1');
  });
});
